/**
 * @file fence_command_delivery.c
 * @brief Fence attribute changes delivered through the fence staged out queue.
 *
 * A fence attribute change (name, description, avatar, limits, permissions) is generated by one
 * member and has to reach every other member. The accept thread only builds and stores the
 * envelope under @c FENCE_OUT_QUEUE:<fid>:<eid>, using the fence event id the change was registered
 * under; a job worker pops the record, relays the command to every target in its snapshot, retries
 * the ones that failed and logs the attempt.
 *
 * The originator's own copy is not queued: it is an acknowledgement of the request it just issued,
 * so it is delivered immediately through @c WireMarshalFenceCommandToUser().
 *
 * Copyright (C) 2015-2026  unfacd works
 *
 * This file is part of ufsrvwebsock source code.
 * Created by ayman on 25/11/2026.
 *
 * This program is free software: you can redistribute it and/or modify
 * it under the terms of the GNU Affero General Public License as published by
 * the Free Software Foundation, either version 3 of the License, or
 * (at your option) any later version.
 *
 */

